'use client'
import {useEffect,useState} from 'react'
import Link from 'next/link'
type M={id:number;title:string;release_date?:string;poster_path?:string|null;slug:string}
export default function Home(){const[q,setQ]=useState('');const[r,setR]=useState<M[]>([]);useEffect(()=>{if(q.trim().length<2){setR([]);return}const t=setTimeout(async()=>{const x=await fetch('/api/search?q='+encodeURIComponent(q));if(x.ok)setR(await x.json())},250);return()=>clearTimeout(t)},[q]);return <main className="home"><section className="hero"><h1>Is this movie <span className="green">good?</span></h1><p className="sub">Quick answer. No spoilers.</p><div className="search"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search for a movie..." aria-label="Search for a movie"/>{r.length>0&&<div className="results">{r.map(m=><Link className="result" href={'/'+m.slug} key={m.id}><img src={m.poster_path?`https://image.tmdb.org/t/p/w92${m.poster_path}`:'/placeholder.svg'} /><span>{m.title}</span><span className="year">{m.release_date?.slice(0,4)}</span></Link>)}</div>}</div><div className="legend"><div><div className="icon">✓</div><b>Green means good</b><p>Worth your time.</p></div><div><div className="icon">×</div><b>Red means bad</b><p>Skip it.</p></div><div><div className="icon">?</div><b>Grey means unrated</b><p>Not enough votes yet.</p></div></div></section></main>}
